function persist(){try{localStorage.setItem(STORE,JSON.stringify({version:1,scene,progress}));}catch(e){if(!dirty)toast('Browser storage is unavailable or full. Use Save file to keep your work.');dirty=true;}}
function checkpoint(){const snapshot=JSON.stringify(scene);history.push(snapshot);checkpoint.bytes=(checkpoint.bytes||0)+snapshot.length*2;while(history.length>1&&(history.length>30||checkpoint.bytes>8*1024*1024))checkpoint.bytes-=history.shift().length*2;}
function stop(){running=false;$('runButton').textContent='▶ Run';$('simStatus').textContent=sim?.time>0?'Paused':'Ready to build';accumulator=0;sim?.keys.clear();syncAttachmentButtons();drawWorld.invalidated=true;}
function rebuild(){stop();sim=new N.Simulation(scene);graphData.clear();lastSample=0;prevSample=null;attempt=null;updateInspector();updateMeasurements();syncWorld();syncFollowControls();syncKeyControls();}
function changed(){Workshop.normalize();normalizeSceneControls();rebuild();persist();}
function syncWorld(){ Workshop.applyDock(false);$('gravityModel').value=scene.gravityModel||'uniform';$('gravityModel').disabled=mode==='challenge';$('gravityValue').value=scene.gravity;$('gravityPreset').value=[9.81,1.62,3.71,0].includes(scene.gravity)?String(scene.gravity):'custom';$('airToggle').checked=scene.air;const locked=mode==='challenge';for(const id of ['gravityPreset','gravityValue','airToggle','stepButton','exampleSelect','undoButton','clearButton'])$(id).disabled=locked;$('simStatus').textContent=running?'Running':sim.time?'Paused':'Ready to build';}
function restoreProgress(p,check=false){
 if(!p||typeof p.name!=='string'||p.name.length>100||!Array.isArray(p.records)||p.records.length>15)throw Error('Invalid progress file.');
 if(p.curriculum!==C.curriculum){const legacy=validateLegacyProgress(p,check);return {curriculum:C.curriculum,name:p.name,completed:[],skipped:[],records:[],attempts:{},legacy};}
 const records=[],seen=new Set();for(const r of p.records){if(!Number.isInteger(r.level)||r.level<0||r.level>=15||seen.has(r.level)||!C.valid(r.level,r.value)||!Number.isFinite(r.actual)||!C.pass(r.level,r.actual))throw Error('Invalid engineering result.');if(check){const result=replay(r.level,r.value);if(!C.pass(r.level,result)||Math.abs(result-r.actual)>Math.max(.1,Math.abs(result)*.03))throw Error('A challenge result could not be reproduced.');}seen.add(r.level);records.push({...r,when:typeof r.when==='string'?r.when.slice(0,40):''});}
 const skipped=Array.isArray(p.skipped)?[...new Set(p.skipped)]:[];if(skipped.some(i=>!Number.isInteger(i)||i<0||i>=15||seen.has(i)))throw Error('Invalid skipped levels.');const resolved=new Set([...seen,...skipped]);for(let i=0;i<=Math.max(-1,...resolved);i++)if(!resolved.has(i))throw Error('Progress must follow the level sequence.');
 return {curriculum:C.curriculum,name:p.name,records:records.sort((a,b)=>a.level-b.level),completed:[...seen].sort((a,b)=>a-b),skipped,attempts:p.attempts||{},...(p.legacy?{legacy:validateLegacyProgress(p.legacy,check)}:{})};
}
function rangeStep(a){if(a)C.tick(a.index,sim,a);}
function replay(index,value){return C.run(index,value).actual;}
