function setMode(next){if(next===mode)return;if(mode==='explore')persist();mode=next;$('buildPanelTitle').textContent=mode==='challenge'?'Your journey':'Build your world';$('buildRailLabel').textContent=mode==='challenge'?'Levels':'Build';stop();selected=null;connectFirst=null;$('exploreTab').classList.toggle('active',mode==='explore');$('challengeTab').classList.toggle('active',mode==='challenge');$('exploreTools').hidden=mode==='challenge';$('challengeTools').hidden=mode==='explore';$('challengeCard').hidden=mode==='explore';$('modeBadge').textContent=mode==='explore'?'EXPLORE':'CHALLENGE';$('canvasTip').textContent=mode==='explore'?'Scroll to zoom · Space + drag to pan · +y points up':'World settings locked · Adjust highlighted design controls and test';Workshop.applyDock(false);if(mode==='challenge'){window.exploreScene=N.copy(scene);window.exploreFollow=$('followToggle').checked;$('followToggle').checked=true;loadLevel(Math.min(unlockedLevel(),C.levels.length-1));}else{scene=window.exploreScene||N.demo();$('followToggle').checked=!!window.exploreFollow;rebuild();fitScene();}updateProgress();}
function collapseChallenge(collapsed){$('challengeCard').classList.toggle('minimized',collapsed);$('collapseChallenge').textContent=collapsed?'Show':'Hide';$('collapseChallenge').setAttribute('aria-expanded',String(!collapsed));$('challengeSummary').hidden=!collapsed;}
