function loadLevel(index){
 if(index<0||index>=15||index>unlockedLevel())return;collapseChallenge(false);$('challengeSummary').textContent='';challengeIndex=index;const l=C.levels[index],record=progress.records.find(r=>r.level===index);challengeValue=C.values(index,record?.value??l.start);scene=C.configure(index,challengeValue);selected=scene.subject||scene.bodies[0].id;trackedId=selected;rebuild();
 $('challengeTopic').textContent=`Level ${index+1} / 15 · ${l.topic}`;$('challengeTitle').textContent=l.title;$('challengeStory').textContent='Build, predict, test, revise.';$('challengePrompt').textContent=l.prompt;hintIndex=0;updateMissionGoal();
 $('challengeVariable').innerHTML='<div class="adjust-heading">YOU CAN ADJUST</div>'+l.fields.map((f,i)=>`<div class="challenge-variable"><label for="${i?'challengeInput_'+f.key:'challengeInput'}">${esc(f.label)}<small>${f.min}–${f.max} ${esc(f.unit)}</small></label><input type="number" data-challenge="${f.key}" id="${i?'challengeInput_'+f.key:'challengeInput'}" value="${challengeValue[f.key]}" min="${f.min}" max="${f.max}" step="${f.step}"><span>${esc(f.unit)}</span></div>`).join('')+`<div class="locked-quantities"><b>LOCKED</b><br>${esc(l.locked)}</div>`;
 document.querySelectorAll('[data-challenge]').forEach(el=>el.onchange=()=>{const v=readDesign();if(!C.valid(index,v)){toast('Check the displayed ranges and resource budget.');return;}challengeValue=v;scene=C.configure(index,v);selected=scene.subject||scene.bodies[0].id;trackedId=selected;rebuild();$('challengeResult').innerHTML='';});
 $('hintText').hidden=true;$('hintButton').textContent='Hint 1 of 3';$('challengeResult').innerHTML='';$('tryButton').disabled=false;$('followToggle').checked=true;updateProgress();fitScene();
}
