function startAttempt(){const v=readDesign(),l=C.levels[challengeIndex];if(!C.valid(challengeIndex,v)){toast('Check allowed ranges, whole-number parts and the resource budget.');return;}challengeValue=v;scene=C.configure(challengeIndex,v);selected=scene.subject||scene.bodies[0].id;rebuild();attempt={...C.begin(challengeIndex,sim),value:N.copy(v)};selected=attempt.shot||selected;trackedId=selected;syncFollowControls();progress.attempts[challengeIndex]=(Number(progress.attempts[challengeIndex])||0)+1;$('challengeResult').innerHTML='<div class="result">Testing your design with automatic controls…</div>';$('tryButton').disabled=true;document.querySelectorAll('[data-challenge]').forEach(el=>el.disabled=true);if(W<600)collapseChallenge(true);start();}
function finishAttempt(){const a=attempt;if(!a)return;const l=C.levels[a.index],actual=C.observe(a.index,sim,a),passed=C.pass(a.index,actual),unit=resultUnit(l.metric);stop();$('tryButton').disabled=false;document.querySelectorAll('[data-challenge]').forEach(el=>el.disabled=false);$('challengeSummary').textContent=`${passed?'✓ Complete':'Try again'} · ${fmt(actual,2)} ${unit}`;
 $('challengeResult').innerHTML=`<div class="result ${passed?'':'fail'}"><b>${passed?esc(l.success):'Revise your design and try again.'}</b><br>Measured ${l.metric==='escape'?'escape margin: ':''}${fmt(actual,2)} ${unit}<br>Goal: ${goalText(l)}${actual===null?'<br>No target crossing / landing detected.':''}${passed&&a.index<14?'<button id="nextLevel" class="run">Next mission</button>':''}</div>`;
 if(passed){const record={level:a.index,value:a.value,actual,when:new Date().toISOString(),attempts:progress.attempts[a.index]},idx=progress.records.findIndex(r=>r.level===a.index);if(idx<0)progress.records.push(record);else progress.records[idx]=record;progress.skipped=progress.skipped.filter(i=>i!==a.index);progress.completed=progress.records.map(r=>r.level).sort((a,b)=>a-b);updateProgress();}persistExplore();if($('nextLevel'))$('nextLevel').onclick=()=>loadLevel(a.index+1);attempt=null;updateMeasurements();}
function persistExplore(){if(mode==='challenge'){try{localStorage.setItem(STORE,JSON.stringify({version:1,scene:window.exploreScene||N.demo(),progress}));}catch(e){toast('Use Save file to keep progress; browser storage is unavailable.');}}else persist();}
function updateProgress(){const count=progress.completed.length;$('progressCount').textContent=`${count}/${C.levels.length}`;$('progressBar').style.width=`${count/C.levels.length*100}%`;$('levelList').innerHTML=C.levels.map((l,i)=>`<button class="level-button ${progress.completed.includes(i)?'done':(progress.skipped||[]).includes(i)?'skipped':''} ${i===challengeIndex?'current':''}" data-level="${i}" ${i>unlockedLevel()?'disabled':''}><span class="level-n">${progress.completed.includes(i)?'✓':(progress.skipped||[]).includes(i)?'↪':i+1}</span><span>${esc(l.title)}</span></button>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>loadLevel(Number(b.dataset.level)));}
