function selectTool(t){tool=t;connectFirst=null;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('selected',b.dataset.tool===t));const hints={select:'Click an object to inspect it. Drag to move; use the square handle to resize and the round handle to rotate (Shift snaps to 15°).',pan:'Drag the canvas to pan in any direction.',terrainAdd:'Paint to raise the surface. The first stroke creates a 40 m terrain patch. Pause before sculpting.',terrainSubtract:'Paint to lower the surface into valleys and trenches. Undo restores one entire stroke.',axle:'Click a dynamic object at the point you want to pin to the world.',motor:'Click a dynamic object to add a motor at that point.',jointAxle:'Click two dynamic objects. The axle is placed at the second click.',rod:'Click two objects to connect their centers with a rigid rod.',weld:'Click two objects to join them rigidly.',mesh:'Bring gear edges close, then click both gears. Nearby gears also snap and connect automatically when dropped.'};$('toolHint').textContent=hints[t]||'Click and drag in the world to draw this object. Ground and launchers are fixed.';}
