function drawThrusterFlames(e){const b=e.spec;if(e.activeThrusters.length)for(const t of e.activeThrusters){const angle=t.angle*Math.PI/180+(t.force<0?Math.PI:0),exit=b.kind==='thruster'?b.w*.5:0,point=displayWorldPoint(e,{x:t.offsetX-exit*Math.cos(angle),y:t.offsetY-exit*Math.sin(angle)}),pt=screenPoint(point.x,point.y),ang=e.renderAngle+angle;ctx.save();ctx.translate(pt.x,pt.y);ctx.rotate(-ang);const size=b.kind==='thruster'?Math.max(3,b.h*camera.scale*.3):6,len=size*(3.2+.6*Math.sin(performance.now()*.018));ctx.beginPath();ctx.moveTo(-1,-size);ctx.lineTo(-len,0);ctx.lineTo(-1,size);ctx.fillStyle='#ffab40';ctx.fill();ctx.beginPath();ctx.moveTo(-1,-size*.5);ctx.lineTo(-len*.6,0);ctx.lineTo(-1,size*.5);ctx.fillStyle='#ffe2a0';ctx.fill();ctx.restore();}}

function arrow(p,v,scale,color,label,unit){const mag=Math.hypot(v.x,v.y);if(mag<.0001)return;const a=screenPoint(p.x,p.y),len=Math.min(160,mag*scale),dx=v.x/mag*len,dy=-v.y/mag*len,b={x:a.x+dx,y:a.y+dy};ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();const ang=Math.atan2(dy,dx);ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-9*Math.cos(ang-.42),b.y-9*Math.sin(ang-.42));ctx.lineTo(b.x-9*Math.cos(ang+.42),b.y-9*Math.sin(ang+.42));ctx.closePath();ctx.fill();if(renderOptions.numbers){const text=`${label} ${fmt(mag)} ${unit}`;ctx.font='11px system-ui';const tw=ctx.measureText(text).width;let x=b.x+6,y=b.y-6;x=Math.max(4,Math.min(W-tw-8,x));y=Math.max(60,Math.min(H-80,y));ctx.fillStyle=darkTheme?'#15243aee':'#ffffffdd';ctx.fillRect(x-3,y-11,tw+6,16);ctx.fillStyle=color;ctx.fillText(text,x,y);}}
