 if($('graphPanel').hidden)return;const metric=$('graphMetric').value,w=graphCanvas.width/dpr,h=graphCanvas.height/dpr,key=[graphData.revision,metric,w,h,darkTheme].join(':');if(drawGraph.key===key)return;drawGraph.key=key;
