 const first=Math.max(0,graphData.length-1200),loT=graphData.get(first).t,hiT=Math.max(loT+1,graphData.get(graphData.length-1).t);let lo=0,hi=0;
 for(let i=first;i<graphData.length;i++){const value=graphData.get(i)[metric];lo=Math.min(lo,value);hi=Math.max(hi,value);}
