let measureTick=0;
function frame(now){
 if(lastFrame===0)lastFrame=now;const elapsed=Math.min(.1,(now-lastFrame)/1000);lastFrame=now;
 if(running){accumulator+=elapsed*Number($('timeScale').value);let n=0;while(accumulator>=N.DT&&n<100){sim.step();Workshop.sampleTrails();accumulator-=N.DT;n++;rangeStep(attempt);sampleGraph();if(attempt&&sim.time>=C.levels[attempt.index].duration-1e-8){finishAttempt();break;}}if(n>=100){accumulator=0;$('simStatus').textContent='Heavy scene — simulation time slows to keep fixed steps';}}
 sim.interpolate(running?accumulator/N.DT:1);
 if(running||frame.wasRunning)updateFollowCamera();frame.wasRunning=running;
 if(now-measureTick>100){measureTick=now;recycleDistantShots();updateMeasurements();}
 drawWorld();if(now-(frame.graphTick||0)>100){drawGraph();frame.graphTick=now;}requestAnimationFrame(frame);
}
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('modal').open)return;if(e.code==='Space'){spaceHeld=true;e.preventDefault();}if(e.key==='Delete'||e.key==='Backspace'){if(mode==='explore'){e.preventDefault();removeSelected();}}if(mode==='explore'&&running){if(activeControlKeys().has(e.key.toLowerCase()))e.preventDefault();const fresh=!sim.keys.has(e.key.toLowerCase());sim.keys.add(e.key.toLowerCase());if(fresh&&!e.repeat&&running){const released=sim.release(e.key);if(released)toast('Payload released. Reset restores the connection.');}if(fresh&&!e.repeat&&running)for(const b of scene.bodies.filter(b=>b.kind==='launcher'&&b.fireKey.toLowerCase()===e.key.toLowerCase()))fireLive(b.id);}});window.addEventListener('keyup',e=>{if(e.code==='Space')spaceHeld=false;sim.keys.delete(e.key.toLowerCase());});window.addEventListener('blur',()=>{sim.keys.clear();spaceHeld=false;});
function openModal(title,html){sim.keys.clear();$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').showModal();}
$('closeModal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
$('helpButton').onclick=()=>openModal('Welcome to Newton Studio',`<p>Build an experiment, run it, and watch how forces change motion.</p><ol><li><b>Draw:</b> choose a shape and drag on the canvas. Ground stays fixed; launchers can be attached to moving objects in the Inspector.</li><li><b>Edit:</b> pause, select an object, and drag it to move. Drag the small square handle to resize; the round handle above an object rotates it (Shift snaps to 15°). Set mass, force, velocity, friction, and bounce in the Inspector.</li><li><b>Panels:</b> toggle Connect &amp; Drive in the top bar. Its Place window menu docks it below Build or to the right; Minimize hides its tools.</li><li><b>Materials:</b> select an object to set density, thickness and friction, save a named material, or fix/unfix the connected assembly. Mass adjusts when you resize. New thrusters are separate parts and appear immediately in the Inspector.</li><li><b>Trails:</b> create a Trace point or Attach trajectory point in the Inspector. Weld it to the moving object, enable its line, and set color, thickness and fade (0 keeps it until Reset).</li><li><b>Refuel:</b> place a green station. Its fuel/oxygen supply, rates and reach are editable; come within reach below 2 m/s to refill attached tanks to capacity.</li><li><b>Connect:</b> a fixed axle pins an object to the world; an axle between objects lets one rotate relative to another. Rods hold centers a fixed distance apart. Welds join objects rigidly.</li><li><b>Drive:</b> add a motor, set rpm and maximum torque, and choose two keys. Enable “Run automatically” or hold a mapped key while running. Thrusters apply forces, with optional offsets for torque.</li><li><b>Measure:</b> select an object, turn on graphs and vectors, and run. Graphs always use simulation time.</li><li><b>Screen space:</b> use Fullscreen in the top bar (Esc exits). Use the chevrons in the Build and Inspector headings to collapse either panel; click the remaining chevron to restore it.</li><li><b>Navigate:</b> scroll to zoom. Use Pan or hold Space while dragging. There are no world edges.</li><li><b>Challenges:</b> adjust the highlighted design controls and test. Complete a mission or skip it for now to unlock the next. Skips are labeled in teacher reports. Tutorials and walkthroughs help you plan your experiment.</li></ol><p>Save file downloads the starting scene and challenge progress. Open file restores it. Share progress creates a report your teacher can open in this app.</p><p class="small">Edits after a run use the current object positions and restart the clock. Reset restores the last edited starting scene. Graph acceleration is averaged over 0.05 s; live vectors use the last 1/240 s step.</p>`);
$('physicsButton').onclick=()=>openModal('Physics model & accuracy',`<p>All physical values use SI units. Positive x is right; positive y is up. Positive rotation is counterclockwise.</p><h3>Forces and integration</h3><p>The app uses Planck.js 1.5.0, a Box2D-based rigid-body engine. It advances at a fixed 1/240 s with semi-implicit Euler integration and an iterative impulse constraint solver (12 velocity / 8 position iterations). Slow computers slow simulation time instead of using larger physics steps.</p><p>Translation follows <b>ΣF = ma</b>, and rotation follows <b>Στ = Iα</b>. Mass and moment of inertia come from uniform density, including tank contents and thruster dry mass. Off-center thrust produces torque. Gravity can be uniform, central Earth gravity or the summed field of Nearby worlds. Fictional miniature worlds use G × mass / r² outside their radius and a uniform-density sphere field inside. Fixed centers are externally supported; unfixed planets receive reaction forces from the simulated bodies. Fueled thrusters consume attached hydrogen fuel and oxygen, reducing tank mass and available chemical energy. Only planet sources attract other bodies in Nearby worlds mode; ordinary objects do not attract each other.</p><h3>Collisions & connections</h3><p>Convex collision shapes, friction, restitution, and continuous collision detection are enabled. Circles are true circles. Sculpted terrain uses connected chain edges with neighboring vertices to reduce internal seam collisions. It is a finite height profile with no overhangs; the displayed edge segments are the collision boundary. Starting inside a solid or extremely fast angular motion can still produce poor contacts. Gear teeth are visual: gear joints impose <b>ω₁ + (teeth₂/teeth₁)ω₂ = 0</b> between fixed axles. Vehicle gearboxes are ideal reductions: output torque = ratio × input torque; output rpm = input rpm / ratio, conserving power at the torque limit. Only neighboring gears with matching tooth spacing connect. Drag a gear near another to snap; drag it away to disconnect. They transfer torque as ideal gears without tooth impacts, slip, or backlash. Motor rpm is a target limited by available torque.</p><p>Ground and terrain are fixed supports. Launchers can be fixed, free moving, or welded to a moving shape. Moving shots inherit the muzzle’s translational and rotational velocity and apply an opposite impulse m × launch speed; fixed supports absorb recoil. Moving launcher housings collide as rectangles; fixed launcher housings are noncolliding supports. The muzzle automatically clears the moving housing to avoid spawning a shot inside it. Projectile mass is supplied externally and does not reduce carrier mass. The engine combines friction as √(μ₁μ₂) and restitution using the larger value. Very slow collisions use no restitution. Rods are ideal rigid center-to-center constraints; they are not physical bars with their own mass or collision shape.</p><h3>Thruster resources & Earth escape</h3><p>Fuel and oxygen tanks are physical bodies: empty hardware mass plus remaining contents. Weld them into the engine’s assembly. Fueled engines use F = mass flow × effective exhaust speed; fuel chemical energy and efficiency bound exhaust energy. Both resources deplete and tank mass falls. Thrust stops when either supply runs out. Resource mode can be disabled for an ideal unlimited external force.</p><p>Earth inverse-square mode uses central gravity toward Earth’s center 6,371 km below the origin. Escape tasks require outward flight and speed at least √(2GM/r); this is a vacuum model without an atmosphere or full planet collision surface. Liftoff alone is not escape.</p><h3>Size, materials & refueling</h3><p>New solids have default density and friction. Automatic mass uses density × area × thickness; fictional spherical worlds use sphere volume. Resizing thruster or motor hardware scales rated thrust or torque with area. This is an adjustable classroom actuator rating model, not an engineering prediction for real engines. Thruster collision fixtures follow the nozzle, chamber and cap. Motor housing mass joins its chassis; fixed motor housings are supported by the world. Rotor inertia and electricity use are not separately modeled.</p><p>Green stations have finite fuel/oxygen supplies. Tanks refill up to their capacity within reach at relative speeds up to 2 m/s. Incoming contents carry the station’s translational velocity. The ideal external pump supplies transfer work and angular redistribution; pipe, liquid flow and thermal effects are not modeled.</p><p>Trajectory points are small 0.01 kg sensor markers. Weld them to objects to trace a location without a collision surface. Fade uses simulation time. Forever paths retain their full span using reduced detail in long runs; Reset clears paths.</p><h3>Air resistance & measurements</h3><p>With air on, <b>Fdrag = −k|v|v</b>; k has units kg/m and combines ½ρCᴅA. You choose k rather than a separate air density and cross-section. This models still air and translational drag only. “Distance” sums the traveled path; “displacement” measures the straight-line change from the start.</p><p>Net force is inferred from mΔv/Δt and includes collision and joint impulses. The contact/joint arrow shows the resultant support and constraint force, found by subtracting the explicitly applied forces from the net force. A collision is not an instantaneous, finite force: its displayed value is averaged over the time step. Graph acceleration and net force use consecutive samples about 0.05 s apart.</p><h3>Numerical limits</h3><p>This is a numerical approximation, not an exact differential-equation solution. Finite steps and iterative constraints produce small errors. Extreme forces, long joint chains, tiny shapes, and fast spins can reduce accuracy. Supported teaching scale: shapes roughly 0.1–20 m, typical speeds below 100 m/s (vacuum space examples support higher speeds), up to 180 authored objects plus 100 live projectiles. There is no fluid flow, deformation, breakage, rolling resistance, or rotational air drag.</p><p>Source and numerical verification tests are included in the download. <a href="https://piqnt.com/planck.js/docs/" target="_blank" rel="noopener">Planck documentation</a></p>`);
function saveFile(){const data={app:'Newton Studio',version:1,scene:mode==='challenge'?(window.exploreScene||N.demo()):scene,progress,savedAt:new Date().toISOString()};download('Newton_Studio_Save.json',JSON.stringify(data,null,2));toast('Scene and progress downloaded.');}
$('saveButton').onclick=saveFile;$('loadButton').onclick=()=>$('fileInput').click();$('fileInput').onchange=async()=>{const file=$('fileInput').files[0];$('fileInput').value='';if(!file)return;if(file.size>2000000){toast('Choose a Newton Studio file smaller than 2 MB.');return;}try{const data=JSON.parse(await file.text());if(data.app==='Newton Studio Progress'){showReport(data);return;}if(data.app!=='Newton Studio'||data.version!==1)throw Error('Choose a Newton Studio save file.');const loaded=N.validate(data.scene),p=await Workshop.checkedProgress(data.progress);if(mode==='challenge')setMode('explore');checkpoint();scene=loaded;progress=p;selected=null;changed();updateProgress();fitScene();toast('Scene and progress restored.');}catch(e){toast(e.message||'Could not open this file.');}};
function report(){return {app:'Newton Studio Progress',version:1,curriculum:C.curriculum,...(progress.legacy?{legacy:progress.legacy}:{}),name:progress.name,records:progress.records,completed:progress.completed,skipped:progress.skipped||[],attempts:progress.attempts,exportedAt:new Date().toISOString()};}
function encodeReport(r){const bytes=new TextEncoder().encode(JSON.stringify(r));let str='';for(const b of bytes)str+=String.fromCharCode(b);return 'NS1.'+btoa(str).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function decodeReport(code){const clean=code.trim().includes('#report=')?code.trim().split('#report=')[1]:code.trim();if(!clean.startsWith('NS1.')||clean.length>30000)throw Error('Paste a valid Newton Studio report code or report URL.');const bin=atob(clean.slice(4).replace(/-/g,'+').replace(/_/g,'/'));return JSON.parse(new TextDecoder().decode(Uint8Array.from(bin,c=>c.charCodeAt(0))));}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch(e){const t=$('reportCode');if(t){t.focus();t.select();toast('Select and copy the code. Clipboard access is unavailable here.');}}}
$('shareButton').onclick=()=>{openModal('Share or review progress',`<p>Enter the name your teacher uses for you. Progress reports stay on your device until you share them.</p><label class="field">Student name<input id="studentName" type="text" maxlength="100" value="${esc(progress.name)}" placeholder="Name or classroom ID"></label><p><b>${progress.completed.length} of ${C.levels.length} levels completed</b> · ${(progress.skipped||[]).length} skipped</p><textarea id="reportCode" readonly aria-label="Progress report code"></textarea><div class="row"><button id="copyCode" class="dark">Copy report code</button><button id="downloadReport">Download report</button><button id="copyLink">Copy report link</button></div><p class="small">Send the code, link, or JSON report to your teacher. A report link opens this same app; it works after the app has been published. Reports can be reproduced by the app but do not prove identity or independent work.</p>${progress.legacy?'<button id="legacyReport">View saved original challenge progress</button>':''}<h3>Teacher: review a report</h3><textarea id="reviewInput" placeholder="Paste a student’s report code or link…" aria-label="Student report to review"></textarea><button id="reviewButton">Open report</button><p class="small">You can also use Open file to review a downloaded progress report. Reviewing a report does not replace your own progress.</p>`);if($('legacyReport'))$('legacyReport').onclick=()=>showLegacyReport({...progress.legacy,app:'Newton Studio Progress',version:1});const refresh=()=>{progress.name=$('studentName').value.slice(0,100);persistExplore();$('reportCode').value=encodeReport(report());};refresh();$('studentName').oninput=refresh;$('copyCode').onclick=()=>copyText($('reportCode').value);$('downloadReport').onclick=()=>download('Newton_Studio_Progress.json',JSON.stringify(report(),null,2));$('copyLink').onclick=()=>{if(location.protocol==='file:'){toast('Use a report code until this app has a published web address.');return;}copyText(location.href.split('#')[0]+'#report='+$('reportCode').value);};$('reviewButton').onclick=()=>{try{const r=decodeReport($('reviewInput').value);showReport(r);}catch(e){toast(e.message);}};};
function resultUnit(metric){return {escape:'m/s',tug:'m',landing:'m',ax:'m/s²',ay:'m/s²',y:'m',x:'m',vx:'m/s',vy:'m/s',range:'m',speed:'m/s',angle:'rad',gearRPM:'rpm'}[metric]||'';}
async function showReport(r){try{if(r.curriculum!==C.curriculum){showLegacyReport(r);return;}if(r.app!=='Newton Studio Progress'||r.version!==1)throw Error('This is not a Newton Studio progress report.');const p=await Workshop.checkedProgress(r);const html=`<p><b>${esc(p.name||'Unnamed student')}</b> completed <b>${p.records.length} / ${C.levels.length}</b> levels. <b>${p.skipped.length}</b> skipped (not completed).</p><p class="small">Exported ${esc(typeof r.exportedAt==='string'?r.exportedAt.slice(0,40):'unknown date')}. Passing results below were reproduced using the locked challenge simulations. This does not verify student identity or independent work.</p><table><thead><tr><th>Level</th><th>Chosen value</th><th>Measured result</th></tr></thead><tbody>${p.records.length?p.records.map(t=>{const l=C.levels[t.level];return `<tr><td>${t.level+1}. ${esc(l.title)}</td><td>${esc(designText(t.level,t.value))}</td><td>${fmt(t.actual,3)} ${esc(resultUnit(C.levels[t.level].metric))}</td></tr>`;}).join(''):'<tr><td colspan="3">No completed levels yet.</td></tr>'}</tbody></table>${p.skipped.length?'<p>Skipped missions: '+p.skipped.map(i=>(i+1)+'. '+esc(C.levels[i].title)).join(', ')+'.</p>':''}<p>This report is read-only. Your scene and progress have not changed.</p><button id="reportCsv">Download results CSV</button>`;$('modal').close();openModal('Student progress report',html);$('reportCsv').onclick=()=>{const quote=s=>'"'+String(s).replace(/"/g,'""')+'"';download('Newton_Studio_Progress.csv','Student,Level,Challenge,Chosen value,Input unit,Measured result,Result unit,Completed at,Status\n'+p.records.map(t=>[p.name,t.level+1,C.levels[t.level].title,designText(t.level,t.value),'SI / shown',t.actual,resultUnit(C.levels[t.level].metric),t.when,'Completed'].map(quote).join(',')).concat(p.skipped.map(i=>[p.name,i+1,C.levels[i].title,'','','','','','Skipped'].map(quote).join(','))).join('\n'),'text/csv');};}catch(e){toast(e.message||'Could not verify this report.');}}
updateProgress();resize();fitScene();sampleGraph();requestAnimationFrame(frame);
if(location.hash.startsWith('#report=')){try{showReport(decodeReport(location.hash.slice(8)));}catch(e){toast(e.message);}}
// A small read-only test hook makes numerical and UI verification reproducible.
window.NewtonApp={get camera(){return {...camera};},get followedObject(){return trackedId;},get scene(){return N.copy(scene);},get sim(){return sim;},get progress(){return N.copy(progress);},get mode(){return mode;},loadLevel,setMode,replay,encodeReport,decodeReport};
// Optional page-scoped tools use the same edit/validation path as file import.
(function registerPageTools(){const mc=document.modelContext;if(!mc?.registerTool)return;const lifecycle=new AbortController();const definitions=[{name:'read_physics_state',title:'Read physics world',description:'Read the starting scene, selected body measurements, simulation time, mode, and completed-level count.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {mode,running,time:sim.time,scene:N.copy(scene),selected:sim.state(selected),completedLevels:progress.completed.length};}},{name:'replace_explore_scene',title:'Replace explore scene',description:'Replace the entire paused Explore scene with a validated Newton Studio scene. Records an undo step and saves locally. Fails in Challenges or while running.',inputSchema:{type:'object',properties:{scene:{type:'object',properties:{version:{const:1},gravity:{type:'number',minimum:-30,maximum:30},air:{type:'boolean'},bodies:{type:'array',maxItems:180,items:{type:'object'}},joints:{type:'array',maxItems:250,items:{type:'object'}}},required:['version','gravity','air','bodies','joints']}},required:['scene'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(mode!=='explore'||running)throw Error('Pause in Explore before replacing the scene.');if(!input||typeof input!=='object'||!input.scene||Object.keys(input).some(k=>k!=='scene'))throw Error('Provide exactly one scene.');const value=N.validate(input.scene);checkpoint();scene=value;selected=null;changed();fitScene();return {bodyCount:scene.bodies.length,jointCount:scene.joints.length,gravity:scene.gravity,air:scene.air};}}];for(const definition of definitions){try{Promise.resolve(mc.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch(e){/* Unsupported experimental interfaces do not affect the app. */}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});})();

// Learning, camera and editor helpers share the same simulation and save paths.
function unlockedLevel(){const resolved=new Set([...progress.completed,...(progress.skipped||[])]);let i=0;while(i<C.levels.length&&resolved.has(i))i++;return Math.min(i,C.levels.length-1);}
function updateMissionGoal(){const l=C.levels[challengeIndex];$('missionGoal').textContent=`Goal: ${goalText(l)} · ${l.duration} simulation seconds · Automatic test`;$('skipButton').textContent=challengeIndex===14?'Mark skipped for now':'Skip for now →';}
function syncFollowControls(){const bodies=[...sim.bodies.values()].filter(e=>e.body.isDynamic());if(!bodies.some(e=>e.spec.id===trackedId))trackedId=bodies.some(e=>e.spec.id===selected)?selected:bodies[0]?.spec.id||null;$('followTarget').innerHTML=bodies.map((e,i)=>`<option value="${esc(e.spec.id)}" ${e.spec.id===trackedId?'selected':''}>${esc(e.spec.name||e.spec.kind+' '+(i+1))}${e.spec.projectile?' (projectile)':''}</option>`).join('');$('followTarget').disabled=!bodies.length;$('followToggle').disabled=!bodies.length;}
function activeControlKeys(){return new Set([...scene.joints.map(j=>j.releaseKey),...scene.joints.filter(j=>j.motor).flatMap(j=>[j.keyPositive,j.keyNegative]),...scene.bodies.flatMap(b=>b.thrusters.filter(t=>!t.always).map(t=>t.key)),...scene.bodies.filter(b=>b.kind==='launcher').flatMap(b=>[b.fireKey,b.aimPositiveKey,b.aimNegativeKey])].filter(Boolean).map(k=>k.toLowerCase()));}
function syncKeyControls(){const rows=[];scene.bodies.forEach((b,i)=>{if(b.kind==='launcher')rows.push(`${b.name||'Launcher '+(i+1)}: tap ${b.fireKey.toUpperCase()} fire · hold ${(b.aimPositiveKey||'i').toUpperCase()}/${(b.aimNegativeKey||'k').toUpperCase()} aim`);b.thrusters.forEach((t,n)=>{if(!t.always)rows.push(`${b.name||b.kind+' '+(i+1)} thrust ${n+1}: hold ${t.key.toUpperCase()}`);});});scene.joints.forEach((j,i)=>{if(j.motor&&!j.auto)rows.push(`Motor ${i+1}: hold ${j.keyPositive.toUpperCase()}/${j.keyNegative.toUpperCase()}`);if(j.releaseKey)rows.push(`Release: tap ${j.releaseKey.toUpperCase()}`);});$('keyControls').hidden=mode!=='explore'||!rows.length;$('keyControls').innerHTML='<details><summary>Keyboard controls ('+rows.length+')</summary>'+rows.map(s=>'<div>'+esc(s)+'</div>').join('')+'</details>';}
function snapGear(id,preferred=null){const b=scene.bodies.find(b=>b.id===id);if(!b||b.kind!=='gear')return false;const margin=Math.min(.5,Math.max(.18,20/camera.scale));const near=scene.bodies.filter(a=>a.kind==='gear'&&a.id!==id&&(!preferred||a.id===preferred)).map(a=>({a,error:Math.abs(Math.hypot(a.x-b.x,a.y-b.y)-a.r-b.r)})).filter(e=>e.error<=margin).sort((a,b)=>a.error-b.error);const a=near[0]?.a;
 // Removing the mesh before creating another prevents stale distant gear constraints.
 scene.joints=scene.joints.filter(j=>j.kind!=='gear'||(j.a!==id&&j.b!==id)||N.gearsAdjacent(scene.bodies.find(k=>k.id===j.a),scene.bodies.find(k=>k.id===j.b)));
 if(!a)return false;
 const radius=a.r*b.teeth/a.teeth;if(radius<.05||radius>20){toast('Matching tooth spacing would exceed the supported gear size.');return false;}
 // A gear train may branch, but adding a loop could demand contradictory rotation.
 const linked=new Set([a.id]);let more=true;while(more){more=false;for(const j of scene.joints.filter(j=>j.kind==='gear')){if(linked.has(j.a)&&!linked.has(j.b)){linked.add(j.b);more=true;}if(linked.has(j.b)&&!linked.has(j.a)){linked.add(j.a);more=true;}}}
 const already=scene.joints.find(j=>j.kind==='gear'&&[j.a,j.b].includes(id)&&[j.a,j.b].includes(a.id));if(linked.has(id)&&!already){toast('This would close a gear loop. Use a branching gear train.');return false;}
 const angle=Math.atan2(b.y-a.y,b.x-a.x),oldX=b.x,oldY=b.y;b.r=radius;b.x=a.x+(a.r+b.r)*Math.cos(angle);b.y=a.y+(a.r+b.r)*Math.sin(angle);
 for(const j of scene.joints.filter(j=>j.kind==='axle'&&j.b===id)){j.x+=b.x-oldX;j.y+=b.y-oldY;}
 function centeredAxle(g){let j=scene.joints.find(j=>j.kind==='axle'&&!j.a&&j.b===g.id&&Math.hypot(j.x-g.x,j.y-g.y)<.015);if(!j)j=addAxle(g.id,{x:g.x,y:g.y});return j;}
 N.resizeMass(b);const ja=centeredAxle(a),jb=centeredAxle(b);scene.joints=scene.joints.filter(j=>j.kind!=='gear'||((j.a!==id&&j.b!==id)||N.gearsAdjacent(scene.bodies.find(g=>g.id===j.a),scene.bodies.find(g=>g.id===j.b)))&&j.id!==already?.id);scene.joints.push({id:N.uid(),kind:'gear',a:a.id,b:b.id,joint1:ja.id,joint2:jb.id,ratio:b.teeth/a.teeth});toast('Gears snapped and connected. Tooth spacing matched; fixed axles added.');return true;
}
function drawMissionMarkers(){if(mode!=='challenge')return;const l=C.levels[challengeIndex];if(!['x','range','y'].includes(l.metric))return;const p=screenPoint(l.metric==='y'?0:l.target,l.metric==='y'?l.target:0);ctx.save();ctx.strokeStyle=darkTheme?'#64dbb8':'#087f65';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=2;ctx.setLineDash([6,6]);ctx.beginPath();if(l.metric==='y'){ctx.moveTo(0,p.y);ctx.lineTo(W,p.y);}else{ctx.moveTo(p.x,55);ctx.lineTo(p.x,H-140);}ctx.stroke();ctx.setLineDash([]);ctx.font='bold 12px system-ui';const text=`TARGET ${l.target} m`;ctx.fillText(text,Math.max(8,Math.min(W-105,p.x+8)),Math.max(90,Math.min(H-150,p.y-12)));ctx.restore();}
function setTheme(dark){darkTheme=!!dark;document.documentElement.dataset.theme=darkTheme?'dark':'light';$('themeButton').textContent=darkTheme?'Light mode':'Dark mode';$('themeButton').setAttribute('aria-pressed',String(darkTheme));try{localStorage.setItem('newton-studio-theme',darkTheme?'dark':'light');}catch(e){}}
$('themeButton').onclick=()=>setTheme(!darkTheme);
try{setTheme((localStorage.getItem('newton-studio-theme')|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'))==='dark');}catch(e){setTheme(false);}
$('followToggle').onchange=()=>{syncFollowControls();if($('followToggle').checked)toast('Camera follows the chosen object while running. Choose another in the menu.');};
$('followTarget').onchange=()=>{trackedId=$('followTarget').value;$('followToggle').checked=true;};
$('skipButton').onclick=()=>{if(attempt){toast('Wait for the test to finish or Reset before skipping.');return;}stop();if(!progress.completed.includes(challengeIndex)&&!(progress.skipped||[]).includes(challengeIndex)){progress.skipped=[...(progress.skipped||[]),challengeIndex];persistExplore();updateProgress();}if(challengeIndex<14)loadLevel(challengeIndex+1);else toast('Journey reached. Skipped missions remain available and are labeled in your report.');};
$('lessonButton').onclick=()=>{const l=C.levels[challengeIndex];openModal(`${challengeIndex+1}. ${l.title} — walkthrough`,`<p>${esc(l.story)}</p><ol>${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><b>Think before testing:</b> predict the direction of motion. After testing, explain why your chosen value worked or how you will revise it.</p><p class="small">All other values are locked. A skipped mission stays available for another attempt.</p>`);};
const tutorials=[{title:'Sculpt terrain and rotate shapes',scene:'terrain',steps:['Select a rectangle, ground or launcher. Drag its round rotate handle; hold Shift for 15° increments, or type Angle in the Inspector.','Pause and choose Raise terrain or Lower / carve terrain. Paint across the surface to make hills or valleys; adjust brush radius for broad hills or fine details.','A stroke over Ground converts that platform into terrain. Start an Empty world for a separate terrain patch. Overlapping ground can still cover carved valleys.','Terrain is a finite height profile: it supports hills and trenches but no caves or overhangs. Undo restores a complete stroke. Run a wheel over it to test your design.']},{title:'Catapult and moving launchers',scene:'catapult',steps:['Press Run. Hold L to swing the catapult arm clockwise and upward. J moves it back. The motor has a torque limit and angle stops.','Tap F while the arm is diagonal to release the payload. Its launch motion comes from the rotating arm. Reset reconnects the payload for another trial.','To build a launcher vehicle, draw a Launcher, then choose Attach to a moving shape under Mount / support in the Inspector. It is placed above that shape; pause and drag to adjust.','Choose a fire key, then Run and tap it once per shot. Moving shots inherit muzzle velocity and give recoil to the mount. The Launcher car example uses A/D to drive and F to fire.']},
 {title:'First experiment: forces and motion',scene:'empty',steps:['Choose Rectangle and drag to draw a block. Pause to move or resize it.','Select Zero gravity. Select the block and set mass to 2 kg and horizontal force to 4 N in the Inspector.','Turn on acceleration vectors and the graph. Choose Velocity x; predict how velocity will change.','Run, then pause and compare acceleration with F/m. Reset restores the starting positions.']},
 {title:'Drive a car and follow it',scene:'car',steps:['The example has two wheel motors and a chassis thruster. Their keys are shown on the canvas.','Check Follow object and choose the rectangle chassis in the menu. The camera keeps following even if you inspect a wheel.','Press Run. Hold D to drive right, A to drive left, and inspect a wheel to change motor torque. Releasing a key turns its actuator off; the car can still coast.','The camera has no boundaries. The road extends over 2 km. Pause to sculpt hills or extend it with additional terrain.']},
 {title:'Build a gear train',scene:'gears',steps:['Pause and choose Gear. Draw another gear close to the edge of an existing one, or drag it there.','Release within about 20 screen pixels of touching: it snaps into contact, matches tooth spacing and connects using centered fixed axles.','Select a gear to change its tooth count. Connected sizes follow tooth ratios. Drag it away to disconnect; its axle remains available.','Select a fixed axle, enable Motor, set rpm and torque. Turn Run automatically off to use its positive and negative keys while running. Gears reverse neighboring rotation.']},
 {title:'Thrusters and projectile launchers',scene:'projectile',steps:['Select the launcher. Set launch speed, angle, projectile mass, Mount / support and its fire key in the Inspector. Press Run, then tap F to fire.','For a rocket, draw and select a dynamic shape, then Add thruster. Choose force, body-relative angle and a single key such as W. Attach fuel and oxygen tanks through the same rigid assembly, or choose unlimited external-force mode for a basic experiment.','Uncheck Always on for key control. Hold the chosen key during a run. Add an offset to produce torque as well as acceleration.','Select the projectile or rocket in the follow menu. Enable a graph to compare its trajectory or speed; switch air resistance on to investigate drag.']},
 {title:'Solve missions and share progress',steps:['Open Challenges. Read the mission story, target and the locked quantities. Only the highlighted design controls can change. Locked quantities and resource budgets are stated explicitly.','Use Walkthrough to plan, then reveal up to three hints. Enter your prediction and test it in the physics world.','Passing a mission earns a completion mark. Skip for now unlocks the next mission; skipped missions can be revisited and never count as completed.','Progress saves automatically on this browser. Save file keeps a portable copy. Share progress produces a code, link or report with completed and skipped missions for your teacher.']}
];
function showTutorial(index){const t=tutorials[index];openModal(t.title,`<ol>${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${t.scene?'<button id="loadTutorial" class="run">Load example and try it</button><p class="small">Loads the example into Explore. Your current world is available with Undo; save a file first if you want a permanent copy.</p>':'<button id="openMissions" class="run">Open challenges</button>'}<button id="backTutorials" class="text-button">All tutorials</button>`);$('backTutorials').onclick=showTutorials;if(t.scene)$('loadTutorial').onclick=()=>{if(mode==='challenge')setMode('explore');checkpoint();scene=example(t.scene);selected=scene.bodies.find(b=>!['ground','launcher','terrain'].includes(b.kind))?.id||null;trackedId=selected;changed();fitScene();if(scene.follow||t.scene==='car')$('followToggle').checked=true;$('modal').close();toast('Example ready. Reopen Tutorials whenever you need the steps.');};else $('openMissions').onclick=()=>{$('modal').close();setMode('challenge');};}
function showTutorials(){openModal('Learn by building',`<p>Choose a short tutorial. Each gives you an experiment to try and a prediction to check.</p><div class="tutorial-list">${tutorials.map((t,i)=>`<button data-tutorial="${i}"><b>${esc(t.title)}</b><span>Step-by-step guide →</span></button>`).join('')}</div>`);document.querySelectorAll('[data-tutorial]').forEach(b=>b.onclick=()=>showTutorial(Number(b.dataset.tutorial)));}
$('tutorialButton').onclick=showTutorials;
syncFollowControls();syncKeyControls();Workshop.init();

function fireLive(id){const e=sim.fire(id);if(!e)toast('Maximum 100 live shots. Reset, or enable distant-shot recycling in Explore.');syncFollowControls();return e;}

function rotationHandle(e){if(!e||['circle','gear','terrain'].includes(e.spec.kind))return null;const p=e.body.getWorldPoint(planck.Vec2(0,e.spec.h/2+30/camera.scale));return screenPoint(p.x,p.y);}
function drawRotationHandle(e){const h=rotationHandle(e);if(!h)return;const top=e.body.getWorldPoint(planck.Vec2(0,e.spec.h/2)),p=screenPoint(top.x,top.y);ctx.save();ctx.strokeStyle=darkTheme?'#9bd7f3':'#285776';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(h.x,h.y);ctx.stroke();ctx.beginPath();ctx.arc(h.x,h.y,7,0,Math.PI*2);ctx.fillStyle=darkTheme?'#24405b':'#fff';ctx.fill();ctx.stroke();ctx.font='11px system-ui';ctx.fillStyle=darkTheme?'#d2e8ff':'#285776';ctx.fillText('rotate',h.x+11,h.y+4);ctx.restore();}
function moveMountedWithHost(host,before,mounts=[]){const delta=host.angle-before.angle,c=Math.cos(delta),s=Math.sin(delta);for(const old of mounts){const b=scene.bodies.find(b=>b.id===old.id);if(!b)continue;const x=old.x-before.x,y=old.y-before.y;b.x=host.x+c*x-s*y;b.y=host.y+s*x+c*y;b.angle=old.angle+delta;}}
function mountLauncher(id,target){if(mode!=='explore'||running){toast('Pause before changing a launcher mount.');updateInspector();return;}const b=scene.bodies.find(b=>b.id===id);if(!b||b.kind!=='launcher')return;checkpoint();editFromLive();delete b.mountId;b.fixed=target==='';if(target&&target!=='free'){const host=scene.bodies.find(b=>b.id===target);if(!host)return;b.mountId=host.id;b.fixed=false;const height=['circle','gear','motor','planet','point'].includes(host.kind)?host.r:host.h/2,offset=height+b.h/2+.08;b.x=host.x-Math.sin(host.angle)*offset;b.y=host.y+Math.cos(host.angle)*offset;b.angle=host.angle;b.muzzleOffset=b.muzzleOffset??1.1;}changed();toast(target&&target!=='free'?'Launcher attached above the selected object. Drag it to adjust its mounting position.':target==='free'?'Launcher is free moving and reacts to recoil.':'Launcher fixed to the world.');}
function chooseTerrain(p){const radius=Number($('terrainRadius').value);return scene.bodies.filter(b=>b.kind==='terrain').find(b=>{const q=sim.bodies.get(b.id).body.getLocalPoint(planck.Vec2(p.x,p.y));return Math.abs(q.x)<=b.w/2+radius;});}
function createTerrainPatch(p){const ground=scene.bodies.find(b=>b.kind==='ground'&&sim.bodies.get(b.id).body.getFixtureList().testPoint(planck.Vec2(p.x,p.y)));let t;if(ground){const top=sim.bodies.get(ground.id).body.getWorldPoint(planck.Vec2(0,ground.h/2));t=N.terrain(top.x,top.y,ground.w,Math.max(4,Math.min(400,Math.round(ground.w/.25))));Object.assign(t,{id:ground.id,angle:ground.angle,friction:ground.friction,restitution:ground.restitution});scene.bodies[scene.bodies.indexOf(ground)]=t;toast('Ground converted to sculptable terrain. Undo restores it.');}else{if(scene.bodies.length>=180){toast('Maximum 180 objects.');return null;}t=N.terrain(p.x,0,40);scene.bodies.push(t);toast('Terrain patch added. Remove overlapping ground to expose valleys.');}Workshop.ready(t,true);sim=new N.Simulation(scene);return t;}
function applyTerrainStroke(p,amount){const b=scene.bodies.find(b=>b.id===drag.id);if(!b)return;const radius=Number($('terrainRadius').value),last=drag.last||p,steps=Math.min(32,Math.max(1,Math.ceil(Math.hypot(p.x-last.x,p.y-last.y)/Math.max(.1,radius*.2))));for(let i=1;i<=steps;i++){const t=i/steps,point=sim.bodies.get(b.id).body.getLocalPoint(planck.Vec2(last.x+(p.x-last.x)*t,last.y+(p.y-last.y)*t));N.sculpt(b,point.x,radius,(tool==='terrainAdd'?1:-1)*Math.min(2,amount)/steps);}N.resizeMass(b);sim.preview([b]);}
function drawTerrainBrush(){if(!brushPoint||mode!=='explore'||running||!['terrainAdd','terrainSubtract'].includes(tool))return;const p=screenPoint(brushPoint.x,brushPoint.y);ctx.save();ctx.beginPath();ctx.arc(p.x,p.y,Number($('terrainRadius').value)*camera.scale,0,Math.PI*2);ctx.fillStyle=tool==='terrainAdd'?'#58bf8830':'#eea36730';ctx.strokeStyle=tool==='terrainAdd'?'#43ad7c':'#dd8840';ctx.fill();ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);ctx.font='bold 14px system-ui';ctx.fillStyle=ctx.strokeStyle;ctx.fillText(tool==='terrainAdd'?'+':'−',p.x-5,p.y+5);ctx.restore();}
$('terrainRadius').oninput=()=>{$('terrainRadiusLabel').textContent=$('terrainRadius').value+' m';};
worldCanvas.addEventListener('pointerleave',()=>{brushPoint=null;});
function catapultScene(){const s=N.empty(),arm=N.body('rectangle',-4,1.8,{w:4,h:.24,mass:2,color:'#b88756',friction:.6,restitution:0}),payload=N.body('circle',-6.35,1.8,{r:.28,mass:.4,color:'#ffa64d',restitution:.25,catapultPayload:true});s.bodies=[N.body('ground',4,-.4,{w:32,h:.8,color:'#526276'}),N.body('ground',-2,.8,{w:.65,h:1.6,color:'#607286'}),arm,payload];s.joints=[{id:N.uid(),kind:'axle',a:null,b:arm.id,x:-2,y:1.8,motor:true,auto:false,rpm:45,torque:160,keyPositive:'j',keyNegative:'l',lowerAngle:-1.4,upperAngle:.08},{id:N.uid(),kind:'weld',a:arm.id,b:payload.id,x:payload.x,y:payload.y,releaseKey:'f'}];return s;}

function readDesign(){return Object.fromEntries([...document.querySelectorAll('[data-challenge]')].map(el=>[el.dataset.challenge,Number(el.value)]));}
function goalText(l){return `${l.rule==='atLeast'?'≥ ':l.rule==='atMost'?'≤ ':''}${l.target}${l.tolerance?' ± '+l.tolerance:''} ${resultUnit(l.metric)}`;}
function designText(i,value){const v=C.values(i,value);return C.levels[i].fields.map(f=>`${f.label}: ${fmt(v[f.key],f.step===1?0:2)} ${f.unit}`).join('; ');}
function freeKey(preferred='f'){const used=activeControlKeys();return [...new Set([preferred,...'fghjklertyuiozxcvbnm1234567890'])].find(k=>!used.has(k))||preferred;}
function normalizeSceneControls(){for(const b of scene.bodies)for(const t of b.thrusters){t.exhaustSpeed??=4500;t.oxygenRatio??=8;t.efficiency??=.8;}const firing=new Set();for(const b of scene.bodies)if(b.kind==='launcher'){if(firing.has(b.fireKey.toLowerCase()))b.fireKey=freeKey('f');firing.add(b.fireKey.toLowerCase());b.aimPositiveKey??='i';b.aimNegativeKey??='k';b.aimRate??=30;}}
function addEquipment(kind,p){if(scene.bodies.length>=180){toast('Maximum 180 objects.');return;}checkpoint();editFromLive();const b=Workshop.ready(N.equipment(kind,p.x,p.y),true);if(kind==='thruster')b.thrusters[0].key=freeKey('w');scene.bodies.push(b);selected=b.id;sim=new N.Simulation(scene);const attached=snapEquipment(b.id);changed();selectTool('select');if(!attached)toast('Drag equipment near a body or another tank/engine to attach. Use Detach in the Inspector to separate it.');}
function equipmentInspector(b){let html='';
 if(['fuel','oxygen'].includes(b.kind))html+=`<div class="property-section"><h3>${b.kind==='fuel'?'Hydrogen fuel / chemical energy':'Oxygen oxidizer'}</h3>${field('Tank contents (kg)','contents',b.contents,0,5000)}${field('Tank capacity (kg)','capacity',b.capacity??b.contents,0,5000)}${b.kind==='fuel'?field('Fuel specific energy (MJ/kg)','specificEnergy',b.specificEnergy,1,150):''}<p class="small">Mass above is the empty tank. Total mass includes contents. Fuel energy = contents × specific energy. Oxygen is carried oxidizer, not taken from the air.</p></div>`;
 if(b.kind==='gearbox')html+=`<div class="property-section"><h3>Ideal gearbox</h3>${field('Reduction (input / output)','ratio',b.ratio,.25,12,.1)}<p class="small">Select each wheel motor and choose this gearbox. Output torque is multiplied and rpm divided by this ratio. The box has its own physical mass.</p></div>`;
 const motors=scene.joints.filter(j=>j.kind==='axle'&&j.motor&&(j.a===b.id||j.b===b.id));for(const j of motors)html+=`<label class="field">Gearbox for motor<select data-gearbox="${j.id}"><option value="">Direct drive (1:1)</option>${scene.bodies.filter(a=>a.kind==='gearbox'&&sim.bodies.get(a.id)?.assemblyIds?.has(j.a)).map((a,i)=>`<option value="${a.id}" ${j.gearboxId===a.id?'selected':''}>Gearbox ${i+1} · ${a.ratio}:1</option>`).join('')}</select></label>`;
 html+=`<label class="field object-selector">Select another object<select id="objectSelector"><option value="">Choose…</option>${scene.bodies.map((a,i)=>`<option value="${a.id}">${esc(a.name||a.kind+' '+(i+1))}</option>`).join('')}</select></label>`;return html;}
function bindEquipmentInspector(b){if($('equipmentMount'))$('equipmentMount').onchange=()=>{if(running||mode!=='explore')return;const id=$('equipmentMount').value;checkpoint();editFromLive();if(id){delete b.mountId;sim=new N.Simulation(scene);attachEquipment(b.id,id);}else detachEquipment(b.id);changed();};
 if($('attachEquipment'))$('attachEquipment').onclick=()=>{if(running||mode!=='explore')return;const target=nearestEquipmentTarget(b);if(!target)return;checkpoint();editFromLive();attachEquipment(b.id,target.id);changed();};
 if($('detachEquipment'))$('detachEquipment').onclick=()=>{if(running||mode!=='explore')return;checkpoint();editFromLive();detachEquipment(b.id);changed();toast('Detached. Drag it near another part to reconnect, or use Attach nearby.');};
 document.querySelectorAll('[data-gearbox]').forEach(el=>el.onchange=()=>{if(running)return;checkpoint();const j=scene.joints.find(j=>j.id===el.dataset.gearbox);delete j.gearboxId;if(el.value)j.gearboxId=el.value;changed();});if($('objectSelector'))$('objectSelector').onchange=()=>{if($('objectSelector').value){selected=$('objectSelector').value;updateInspector();}};}
function bodyVisible(e){const p=e.renderPosition,s=e.spec,r=e.renderRadius,q=screenPoint(p.x,p.y),margin=r*camera.scale+180;return q.x>=-margin&&q.x<=W+margin&&q.y>=-margin&&q.y<=H+margin;}
function legacyReplay(index,value){const l=LegacyChallenges.levels[index],s=new N.Simulation(LegacyChallenges.configure(index,value));let range=null,shot=null;if(l.metric==='range')shot=s.fire(s.scene.bodies[0].id).spec.id;for(let i=0;i<Math.round(l.duration/N.DT);i++){s.step();if(shot&&range===null){const e=s.bodies.get(shot),p=e.body.getPosition(),q=e.previous;if(s.time>.04&&q.y>0&&p.y<=0&&e.body.getLinearVelocity().y<0)range=q.x+(p.x-q.x)*q.y/(q.y-p.y);}}return LegacyChallenges.observe(index,s,range);}
function validateLegacyProgress(p,check){if(!p||typeof p.name!=='string'||p.name.length>100||!Array.isArray(p.records)||p.records.length>15)throw Error('Invalid original progress.');const seen=new Set();for(const r of p.records){const l=LegacyChallenges.levels[r.level];if(!l||seen.has(r.level)||!Number.isFinite(r.value)||r.value<l.min||r.value>l.max||l.variable==='teeth'&&!Number.isInteger(r.value)||!Number.isFinite(r.actual)||!LegacyChallenges.pass(r.level,r.actual)||check&&Math.abs(legacyReplay(r.level,r.value)-r.actual)>Math.max(.1,Math.abs(r.actual)*.03))throw Error('Invalid original challenge record.');seen.add(r.level);}return {name:p.name,records:p.records,completed:[...seen],skipped:Array.isArray(p.skipped)?p.skipped.filter(i=>Number.isInteger(i)&&i>=0&&i<15&&!seen.has(i)):[],attempts:p.attempts||{}};}
function showLegacyReport(r){if($('modal').open)$('modal').close();const p=validateLegacyProgress(r,true);openModal('Original challenge progress',`<p><b>${esc(p.name||'Student')}</b> completed ${p.records.length}/15 original missions. These marks are preserved separately from the new engineering curriculum.</p><table><thead><tr><th>Mission</th><th>Value</th><th>Result</th></tr></thead><tbody>${p.records.map(t=>`<tr><td>${t.level+1}. ${esc(LegacyChallenges.levels[t.level].title)}</td><td>${fmt(t.value,3)} ${esc(LegacyChallenges.levels[t.level].unit)}</td><td>${fmt(t.actual,3)} ${resultUnit(LegacyChallenges.levels[t.level].metric)}</td></tr>`).join('')}</tbody></table><p>${p.skipped.length} skipped. The engineering journey starts fresh.</p>`);}
$('earthGravityToggle').onchange=()=>{if(mode!=='explore')return;checkpoint();scene.gravityModel=$('earthGravityToggle').checked?'earth':'uniform';if(scene.gravityModel==='earth'){scene.gravity=9.81;scene.air=false;toast('Central Earth gravity enabled. Vacuum flight; no atmospheric model.');}changed();};
const syncWorldOriginal=syncWorld;syncWorld=function(){syncWorldOriginal();$('earthGravityToggle').checked=scene.gravityModel==='earth';$('earthGravityToggle').disabled=mode==='challenge';$('gravityValue').disabled=mode==='challenge'||scene.gravityModel==='earth'||scene.gravityModel==='planets';$('gravityPreset').disabled=$('gravityValue').disabled;};syncWorld();
const measurementsOriginal=updateMeasurements;updateMeasurements=function(){measurementsOriginal();updateResourceDisplay();};
function recycleDistantShots(){if(mode!=='explore'||!$('recycleShots').checked)return;let count=0;for(const id of [...sim.shots]){const e=sim.bodies.get(id);if(!e||id===selected||id===trackedId||sim.time-e.bornAt<30)continue;const p=e.body.getPosition();if(Math.abs(p.x-camera.x)>W/(2*camera.scale)+100||Math.abs(p.y-camera.y)>H/(2*camera.scale)+100)if(sim.removeProjectile(id))count++;}if(count)syncFollowControls();}
tutorials.unshift({title:'Engineering missions and rocket resources',scene:'rocket',steps:['Choose a mission and read its highlighted adjustable controls and LOCKED quantities. Multi-part builds also state their budget.','Test my design uses automatic controls for comparable results. Explore examples let you use each device’s keyboard mappings.','A fueled spacecraft needs a hull, thruster hardware, fuel tank and oxygen tank in one welded assembly. Tank Mass means empty hardware; contents add to total mass.','Hold W while running the spacecraft example. Watch fuel, oxygen and chemical energy decline. Engine shuts down when a required supply empties. Inverse-square Earth gravity and escape energy are separate from basic liftoff.']});

function updateFollowCamera(){if(!$('followToggle').checked||!trackedId)return;const e=sim.bodies.get(trackedId);if(!e)return;const p=e.renderPosition,offset=mode==='challenge'&&W>600?Math.min(420,W*.5):0;camera.x=p.x-offset/(2*camera.scale);camera.y=p.y+(mode==='challenge'&&W<=600?H*.17/camera.scale:0);}
function displayWorldPoint(e,local){const c=Math.cos(e.renderAngle),s=Math.sin(e.renderAngle);return {x:e.renderPosition.x+c*local.x-s*local.y,y:e.renderPosition.y+s*local.x+c*local.y};}
function displayJointAnchor(joint,first,spec){if(sim.previewing&&spec){if(spec.kind==='rod'){const body=sim.bodies.get(first?spec.a:spec.b);return body?body.renderPosition:(first?joint.getAnchorA():joint.getAnchorB());}const source=spec.mount?sim.bodies.get(spec.b)?.spec:scene.joints.find(j=>j.id===spec.id)||spec;return {x:source.x,y:source.y};}const world=first?joint.getAnchorA():joint.getAnchorB(),body=first?joint.getBodyA():joint.getBodyB(),e=sim.bodies.get(body.getUserData());return e?displayWorldPoint(e,body.getLocalPoint(world)):world;}

// Snap connections are ordinary rigid mounts; the solver and resource model are unchanged.
function isEquipment(b){return !!b&&['fuel','oxygen','thruster','gearbox','motor','point'].includes(b.kind);}
function equipmentTargetAllowed(b){return !!b&&!['ground','terrain'].includes(b.kind)&&!b.fixed&&!(b.kind==='launcher'&&b.fixed!==false&&!b.mountId);}
function equipmentDescendants(id){const ids=new Set([id]),result=[];for(let more=true;more;){more=false;for(const b of scene.bodies)if(b.mountId&&ids.has(b.mountId)&&!ids.has(b.id)){ids.add(b.id);result.push(b);more=true;}}return result;}
function equipmentAttached(b){return !!b.mountId||scene.bodies.some(a=>a.mountId===b.id)||scene.joints.some(j=>j.kind==='weld'&&(j.a===b.id||j.b===b.id));}
function equipmentPlacement(b,target){
 const entry=sim.bodies.get(target.id);if(!entry)return null;
 const body=entry.body,local=body.getLocalPoint(planck.Vec2(b.x,b.y));let q,nx,ny,inside=false;
 if(['circle','gear','motor','planet','point'].includes(target.kind)){
  const length=Math.hypot(local.x,local.y);nx=length?local.x/length:1;ny=length?local.y/length:0;q={x:nx*target.r,y:ny*target.r};inside=length<target.r;
 }else{
  const vertices=target.kind==='triangle'?[{x:-target.w/2,y:-target.h/3},{x:target.w/2,y:-target.h/3},{x:0,y:2*target.h/3}]:[{x:-target.w/2,y:-target.h/2},{x:target.w/2,y:-target.h/2},{x:target.w/2,y:target.h/2},{x:-target.w/2,y:target.h/2}];
  let best=Infinity;for(let i=0;i<vertices.length;i++){const a=vertices[i],c=vertices[(i+1)%vertices.length],dx=c.x-a.x,dy=c.y-a.y,t=Math.max(0,Math.min(1,((local.x-a.x)*dx+(local.y-a.y)*dy)/(dx*dx+dy*dy))),point={x:a.x+t*dx,y:a.y+t*dy},distance=Math.hypot(point.x-local.x,point.y-local.y);if(distance<best){best=distance;q=point;nx=dy/Math.hypot(dx,dy);ny=-dx/Math.hypot(dx,dy);}}
  inside=containsPoint(body,planck.Vec2(b.x,b.y));
  if(!inside&&best>1e-8){nx=(local.x-q.x)/best;ny=(local.y-q.y)/best;}
 }
 const angle=body.getAngle(),c=Math.cos(angle),s=Math.sin(angle),normal={x:c*nx-s*ny,y:s*nx+c*ny},world=body.getWorldPoint(planck.Vec2(q.x,q.y)),relative=Math.atan2(normal.y,normal.x)-b.angle;
 const extent=Math.abs(Math.cos(relative))*b.w/2+Math.abs(Math.sin(relative))*b.h/2,distance=Math.hypot(b.x-world.x,b.y-world.y);
 return {gap:(inside?-distance:distance)-extent,x:world.x+normal.x*(extent+.04),y:world.y+normal.y*(extent+.04)};
}
function nearestEquipmentTarget(b){
 if(!isEquipment(b))return null;const connected=sim.bodies.get(b.id)?.assemblyIds||new Set([b.id]);let nearest=null,score=Infinity;
 for(const target of scene.bodies){if(connected.has(target.id)||!equipmentTargetAllowed(target))continue;const placement=equipmentPlacement(b,target);if(!placement||placement.gap>20/camera.scale)continue;const value=Math.max(0,placement.gap)+Math.hypot(b.x-target.x,b.y-target.y)*1e-6;if(value<score){score=value;nearest={id:target.id,...placement};}}
 return nearest;
}
function attachEquipment(id,targetId){
 const b=scene.bodies.find(b=>b.id===id),target=scene.bodies.find(b=>b.id===targetId);
 if(!isEquipment(b)||!equipmentTargetAllowed(target)||id===targetId||equipmentDescendants(id).some(a=>a.id===targetId)||sim.bodies.get(id)?.assemblyIds.has(targetId))return false;
 const placement=equipmentPlacement(b,target);if(!placement)return false;
 if(!b.mountId&&scene.joints.length+scene.bodies.filter(b=>b.mountId).length>=250){toast('Maximum 250 connections. Remove a connection first.');return false;}
 const before=N.copy(b),children=N.copy(equipmentDescendants(id));b.mountId=targetId;b.x=placement.x;b.y=placement.y;moveMountedWithHost(b,before,children);toast(`${b.kind==='thruster'?'Engine':b.kind} attached to ${target.name||target.kind}. Tanks in this assembly can feed its engines.`);return true;
}
function detachEquipment(id){const b=scene.bodies.find(b=>b.id===id);if(!b)return;delete b.mountId;for(const child of scene.bodies)if(child.mountId===id)delete child.mountId;scene.joints=scene.joints.filter(j=>j.kind!=='weld'||j.a!==id&&j.b!==id);}
function snapEquipment(id){const b=scene.bodies.find(b=>b.id===id);if(!isEquipment(b)||b.mountId)return false;const target=nearestEquipmentTarget(b);return !!target&&attachEquipment(id,target.id);}
function drawEquipmentPreview(){
 if(!drag||drag.kind!=='move'||running||mode!=='explore')return;const b=scene.bodies.find(b=>b.id===drag.id);if(!isEquipment(b)||b.mountId)return;const target=nearestEquipmentTarget(b);if(!target)return;const e=sim.bodies.get(target.id),p=screenPoint(e.spec.x,e.spec.y),radius=e.renderRadius*camera.scale;
 ctx.save();ctx.strokeStyle='#32d6a5';ctx.lineWidth=3;ctx.setLineDash([5,4]);ctx.strokeRect(p.x-radius-5,p.y-radius-5,2*radius+10,2*radius+10);ctx.setLineDash([]);const q=screenPoint(b.x,b.y);ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.font='bold 12px system-ui';ctx.fillStyle=darkTheme?'#153328':'#e0fff2';ctx.fillRect(q.x-50,q.y-36,104,21);ctx.fillStyle=darkTheme?'#8df9cf':'#09654c';ctx.fillText('Release to attach',q.x-46,q.y-21);ctx.restore();
}
function tankPath(w,h,kind){
 if(kind==='fuel')ctx.roundRect(-w/2,-h/2,w,h,Math.min(w,h)*.23);
 else{ctx.moveTo(-w/2,-h*.32);ctx.bezierCurveTo(-w/2,-h*.58,w/2,-h*.58,w/2,-h*.32);ctx.lineTo(w/2,h*.32);ctx.bezierCurveTo(w/2,h*.58,-w/2,h*.58,-w/2,h*.32);ctx.closePath();}
}
function drawTankDetails(e){
 const b=e.spec,w=b.w*camera.scale,h=b.h*camera.scale,show=b.kind==='fuel'?renderOptions.fuel:renderOptions.oxygen,ratio=e.initialContents?Math.max(0,Math.min(1,b.contents/e.initialContents)):0;
 ctx.save();ctx.beginPath();tankPath(w,h,b.kind);ctx.clip();ctx.fillStyle=b.kind==='fuel'?'#5c321b':'#153a68';ctx.globalAlpha=.5;ctx.fillRect(-w/2,-h/2,w,h);ctx.globalAlpha=1;
 if(show){ctx.fillStyle=b.kind==='fuel'?'#ffbb55':'#6ebeff';ctx.fillRect(-w/2,h/2-h*ratio,w,h*ratio);}
 ctx.strokeStyle='#ffffff80';ctx.lineWidth=Math.max(1,Math.min(3,w*.05));ctx.beginPath();if(b.kind==='fuel'){ctx.moveTo(-w/2,-h*.25);ctx.lineTo(w/2,-h*.25);ctx.moveTo(-w/2,h*.25);ctx.lineTo(w/2,h*.25);}else{ctx.ellipse(0,-h*.32,w/2,h*.13,0,0,Math.PI*2);ctx.moveTo(-w*.26,-h*.35);ctx.lineTo(-w*.26,h*.35);}ctx.stroke();ctx.restore();
 if(show&&w>25){ctx.fillStyle=darkTheme?'#e4f4ff':'#203b54';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText(fmt(b.contents,b.contents<10?1:0)+' kg',0,h/2+13);ctx.textAlign='start';}
}
function drawEngineDetails(e){const b=e.spec;for(const t of b.thrusters){ctx.save();ctx.translate(t.offsetX*camera.scale,-t.offsetY*camera.scale);ctx.rotate(-t.angle*Math.PI/180);const w=b.w*camera.scale,h=b.h*camera.scale;ctx.fillStyle='#253a50';ctx.fillRect(-w*.08,-h*.29,w*.4,h*.58);ctx.strokeStyle=selected===b.id?'#72e6c0':'#fff9';ctx.lineWidth=selected===b.id?2.5:1;ctx.strokeRect(-w*.08,-h*.29,w*.4,h*.58);ctx.fillStyle='#adbccc';ctx.beginPath();ctx.moveTo(-w*.08,-h*.17);ctx.lineTo(-w*.5,-h*.35);ctx.lineTo(-w*.5,h*.35);ctx.lineTo(-w*.08,h*.17);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ffb65c';ctx.fillRect(w*.32,-h*.19,w*.16,h*.38);ctx.strokeRect(w*.32,-h*.19,w*.16,h*.38);ctx.restore();}}

function updateResourceDisplay(){
 const showFuel=$('fuelLevelsToggle').checked,showOxygen=$('oxygenLevelsToggle').checked,hud=$('resourceHud');
 const engines=sim.fueledEngines,entry=sim.bodies.get(selected)||sim.bodies.get(trackedId),source=entry?.fuelTanks?.length||entry?.oxygenTanks?.length?entry:engines[0];
 const hidden=(!showFuel&&!showOxygen)||!source;if(hud.hidden!==hidden)hud.hidden=hidden;if(hidden)return;const top=Math.max(W<=600?98:105,$('keyControls').hidden?0:$('keyControls').offsetTop+$('keyControls').offsetHeight+8)+'px';if(hud.style.top!==top)hud.style.top=top;const assemblyEngines=source.assembly?.engines||[];
 const resource=sim.resources(source.spec.id),fuelCapacity=source.assembly?.fuelCapacity||0,oxygenCapacity=source.assembly?.oxygenCapacity||0;
 const row=(label,amount,capacity,kind)=>`<div class="resource-row"><span>${label}</span><strong>${fmt(amount,amount<10?2:1)} / ${fmt(capacity,capacity<10?2:1)} kg</strong><div class="resource-meter ${kind}" role="progressbar" aria-label="${label} remaining" aria-valuemin="0" aria-valuemax="${capacity||1}" aria-valuenow="${amount}"><i style="width:${capacity?Math.max(0,Math.min(100,amount/capacity*100)):0}%"></i></div></div>`;
 const html='<b>Connected tank levels</b>'+(showFuel?row('Fuel',resource.fuel,fuelCapacity,'fuel'):'')+(showOxygen?row('Oxygen',resource.oxygen,oxygenCapacity,'oxygen'):'')+`<div>Energy ${fmt(resource.energy,1)} MJ</div>`+(assemblyEngines.length?`<div>${resource.fuel>0&&resource.oxygen>0?(assemblyEngines.some(e=>e.activeThrusters.length)?'Engine burning':mode==='challenge'?'Automatic test engine':'Run, then hold the engine’s mapped key'):'Attach filled fuel + oxygen tanks'}</div>`:'');if(updateResourceDisplay.html!==html){hud.innerHTML=html;updateResourceDisplay.html=html;}
}
for(const id of ['fuelLevelsToggle','oxygenLevelsToggle']){
 try{const saved=localStorage.getItem('newton-studio-'+id);if(saved!==null)$(id).checked=saved==='true';}catch(e){}
 $(id).onchange=()=>{try{localStorage.setItem('newton-studio-'+id,String($(id).checked));}catch(e){}updateResourceDisplay();};
}

function equipmentAttachmentInspector(b){if(!isEquipment(b))return '';
 const near=nearestEquipmentTarget(b),parent=scene.bodies.find(a=>a.id===b.mountId),attached=equipmentAttached(b),blocked=running||mode!=='explore';
 return `<div class="property-section"><h3>Attach equipment</h3><p class="attachment-status">${attached?'● Attached'+(parent?' to '+esc(parent.name||parent.kind):' assembly'):'○ Free moving'}</p><div class="row"><button id="attachEquipment" ${blocked||!near||!!b.mountId?'disabled':''}>Attach nearby</button><button id="detachEquipment" ${blocked||!attached?'disabled':''}>Detach</button></div><label class="field spaced">Moving host<select id="equipmentMount" ${blocked?'disabled':''}><option value="">Free moving / detach</option>${scene.bodies.filter(a=>a.id!==b.id&&equipmentTargetAllowed(a)&&!equipmentDescendants(b.id).some(k=>k.id===a.id)).map((a,i)=>`<option value="${a.id}" ${b.mountId===a.id?'selected':''}>${esc(a.name||a.kind+' '+(i+1))}</option>`).join('')}</select></label><p class="small">Drop near a body, tank or engine to snap and attach. A green outline previews the connection. Parts need a rigid attachment to share fuel and oxygen.</p></div>`;

}

function syncAttachmentButtons(){const b=scene.bodies.find(b=>b.id===selected),blocked=running||mode!=='explore';if($('attachEquipment'))$('attachEquipment').disabled=blocked||!b||!!b.mountId||!nearestEquipmentTarget(b);if($('detachEquipment'))$('detachEquipment').disabled=blocked||!b||!equipmentAttached(b);if($('equipmentMount'))$('equipmentMount').disabled=blocked;}

function setReadout(id,text){const element=$(id);if(element.textContent!==text)element.textContent=text;}
